create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique,full_name text,is_admin boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.itineraries(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,subtitle text,destination text,duration text,season text,version text,intro text,cover_image text,overview jsonb not null default '{}'::jsonb,content jsonb not null default '{"sections":[]}'::jsonb,status text not null default 'draft' check(status in('draft','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.itinerary_access(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,itinerary_id uuid not null references public.itineraries(id) on delete cascade,access_expires_at timestamptz,created_at timestamptz not null default now(),unique(user_id,itinerary_id));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1))) on conflict(id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert or update of email on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end;$$;
drop trigger if exists itineraries_set_updated_at on public.itineraries; create trigger itineraries_set_updated_at before update on public.itineraries for each row execute procedure public.set_updated_at();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select coalesce((select is_admin from public.profiles where id=auth.uid()),false); $$;
alter table public.profiles enable row level security; alter table public.itineraries enable row level security; alter table public.itinerary_access enable row level security;
create policy "users read own profile" on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy "admins update profiles" on public.profiles for update using(public.is_admin()) with check(public.is_admin());
create policy "customers read granted published itineraries" on public.itineraries for select using(public.is_admin() or(status='published' and exists(select 1 from public.itinerary_access a where a.itinerary_id=itineraries.id and a.user_id=auth.uid() and(a.access_expires_at is null or a.access_expires_at>now()))));
create policy "admins manage itineraries" on public.itineraries for all using(public.is_admin()) with check(public.is_admin());
create policy "users read own access" on public.itinerary_access for select using(user_id=auth.uid() or public.is_admin());
create policy "admins manage access" on public.itinerary_access for all using(public.is_admin()) with check(public.is_admin());
create or replace function public.grant_itinerary_access_by_email(customer_email text,itinerary_slug text,expires_at_value timestamptz default null) returns text language plpgsql security definer set search_path=public,auth as $$ declare target_user uuid;target_itinerary uuid;begin if not public.is_admin() then raise exception 'Apenas administradores podem liberar acessos.';end if;select id into target_user from auth.users where lower(email)=lower(customer_email) limit 1;if target_user is null then raise exception 'Essa pessoa ainda não criou a conta.';end if;select id into target_itinerary from public.itineraries where slug=itinerary_slug limit 1;if target_itinerary is null then raise exception 'Roteiro não encontrado.';end if;insert into public.itinerary_access(user_id,itinerary_id,access_expires_at) values(target_user,target_itinerary,expires_at_value) on conflict(user_id,itinerary_id) do update set access_expires_at=excluded.access_expires_at;return 'Acesso liberado para '||customer_email||' ✨';end;$$;
grant execute on function public.grant_itinerary_access_by_email(text,text,timestamptz) to authenticated;